package com.bank.catalog;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class AddOnPackageGenerator {

    private static final Logger log = Logger.getLogger(AddOnPackageGenerator.class.getName());

    public List<List<Integer>> subsets(int[] addOnIds) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(addOnIds, 0, new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " add-on packages");
        return result;
    }

    private void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> result) {
        result.add(new ArrayList<>(path));            // record every node (incl. empty)
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);                         // include nums[i]
            backtrack(nums, i + 1, path, result);      // recurse forward only
            path.remove(path.size() - 1);              // backtrack (exclude)
        }
    }
}
