package com.bank.catalog;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class SubsetsDemo {

    private static final Logger log = Logger.getLogger(SubsetsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Add-On Package Generator (Subsets)");
        int[] addOns = {1, 2, 3}; // 1=SMS alerts, 2=lounge, 3=insurance
        AddOnPackageGenerator gen = new AddOnPackageGenerator();
        gen.subsets(addOns).forEach(pkg -> log.info("Package: " + pkg));
    }
}
